import {describe, expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const provider: AIProvider = {
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    yield {type: 'stop', stopReason: 'end_turn'};
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
};

describe('beforeSession failure', () => {
  // specs/hal-engine-config-hooks/spec.md#7
  it('passes the session and failure to onError when beforeSession throws', async () => {
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const failure = new Error('setup failed');
    let received: unknown;
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
      hooks: {
        beforeSession: async () => { throw failure; },
        onError: async (hookSession, error) => { received = [hookSession, error]; },
      },
    });

    await orchestrator.processMessage(session).catch(() => undefined);
    expect(received).toEqual([session, failure]);
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/chatOrchestrator.beforeSession.test.ts"
